TLM.f("Sancti/02-02",{"officium":"In Purificatione Beatæ Mariæ Virginis","rule":["Gloria","Credo","Prefatio=Nat","omit commemoratio incipit","Festum Domini","Prelude"],"ruleInherited":["Gloria","Credo","Prefatio=Maria=Festivitate","Gloria","Suffr=Spiritu;Ecclesiæ,Papa;;","Prefatio=Maria=veneratione;"],"fallback":"Commune/C11","from":{"GradualeP":"Commune/C11"},"sections":{"Introitus":[{"k":"ref","la":"Ps 47:10-11"},{"k":"text","la":"Suscépimus, Deus, misericórdiam tuam in médio templi tui: secúndum nomen tuum, Deus, ita et laus tua in fines terræ: justítia plena est déxtera tua."},{"k":"ref","la":"Ps 47:2"},{"k":"text","la":"Magnus Dóminus, et laudábilis nimis: in civitáte Dei nostri, in monte sancto ejus."},{"k":"macro","name":"Gloria"},{"k":"text","la":"Suscépimus, Deus, misericórdiam tuam in médio templi tui: secúndum nomen tuum, Deus, ita et laus tua in fines terræ: justítia plena est déxtera tua."}],"Oratio":[{"k":"text","la":"Omnípotens sempitérne Deus, majestátem tuam súpplices exorámus: ut, sicut unigénitus Fílius tuus hodiérna die cum nostræ carnis substántia in templo est præsentátus; ita nos fácias purificátis tibi méntibus præsentári."},{"k":"macro","name":"Per eundem"}],"Lectio":[{"k":"text","la":"Léctio Malachíæ Prophétæ"},{"k":"ref","la":"Malach 3:1-4"},{"k":"text","la":"Hæc dicit Dóminus Deus: Ecce, ego mitto Angelum meum, et præparábit viam ante fáciem meam. Et statim véniet ad templum suum Dominátor, quem vos quæritis, et Angelus testaménti, quem vos vultis. Ecce, venit, dicit Dóminus exercítuum: et quis póterit cogitáre diem advéntus ejus, et quis stabit ad vidéndum eum? Ipse enim quasi ignis conflans et quasi herba fullónum: et sedébit conflans et emúndans argéntum, et purgábit fílios Levi et colábit eos quasi aurum et quasi argéntum: et erunt Dómino offeréntes sacrifícia in justítia. Et placébit Dómino sacrifícium Juda et Jerúsalem, sicut dies sǽculi et sicut anni antíqui: dicit Dóminus omnípotens."}],"Graduale":[{"k":"ref","la":"Ps 47:10-11; 47:9"},{"k":"text","la":"Suscépimus, Deus, misericórdiam tuam in médio templi tui: secúndum nomen tuum, Deus, ita et laus tua in fines terræ."},{"k":"text","la":"Sicut audívimus, ita et vídimus in civitáte Dei nostri, in monte sancto ejus.","mark":"V"},{"k":"text","la":"Allelúja, allelúja."},{"k":"text","la":"Senex Púerum portábat: Puer autem senem regébat. Allelúja.","mark":"V"}],"GradualeP":[{"k":"text","la":"Allelúja, allelúja."},{"k":"ref","la":"Num 17:8"},{"k":"text","la":"Virga Jesse flóruit: Virgo Deum et hóminem génuit: pacem Deus réddidit, in se reconcílians ima summis"},{"k":"ref","la":"Luke 1:28"},{"k":"text","la":"Ave, María, grátia plena; Dóminus tecum: benedícta tu in muliéribus. Allelúja."}],"Tractus":[{"k":"ref","la":"Ps 47:10-11; 47:9"},{"k":"text","la":"Suscépimus, Deus, misericórdiam tuam in médio templi tui: secúndum nomen tuum, Deus, ita et laus tua in fines terræ."},{"k":"text","la":"Sicut audívimus, ita et vídimus in civitáte Dei nostri, in monte sancto ejus.","mark":"V"},{"k":"ref","la":"Luc 2:29-32"},{"k":"text","la":"Nunc dimíttis servum tuum, Dómine, secúndum verbum tuum in pace."},{"k":"text","la":"Quia vidérunt óculi mei salutáre tuum.","mark":"V"},{"k":"text","la":"V.. Quod parásti ante fáciem ómnium populórum."},{"k":"text","la":"V.. Lumen ad revelatiónem géntium et glóriam plebis tuæ Israël."}],"Evangelium":[{"k":"text","la":"Sequéntia ✠ sancti Evangélii secúndum Lucam"},{"k":"ref","la":"Luc 2:22-32"},{"k":"text","la":"In illo témpore: Postquam impleti sunt dies purgatiónis Maríæ, secúndum legem Moysi, tulérunt Jesum in Jerúsalem, ut sísterent eum Dómino, sicut scriptum est in lege Dómini: Quia omne masculínum adapériens vulvam sanctum Dómino vocábitur. Et ut darent hóstiam, secúndum quod dictum est in lege Dómini, par túrturum aut duos pullos columbárum. Et ecce, homo erat in Jerúsalem, cui nomen Símeon, et homo iste justus et timorátus, exspéctans consolatiónem Israël, et Spíritus Sanctus erat in eo. Et respónsum accéperat a Spíritu Sancto, non visúrum se mortem, nisi prius vidéret Christum Dómini. Et venit in spíritu in templum. Et cum indúcerent púerum Jesum parentes ejus, ut fácerent secúndum consuetúdinem legis pro eo: et ipse accépit eum in ulnas suas, et benedíxit Deum, et dixit: Nunc dimíttis servum tuum, Dómine, secúndum verbum tuum in pace: Quia vidérunt óculi mei salutáre tuum: Quod parásti ante fáciem ómnium populórum: Lumen ad revelatiónem géntium et glóriam plebis tuæ Israël."}],"Offertorium":[{"k":"ref","la":"Ps 44:3"},{"k":"text","la":"Diffúsa est grátia in lábiis tuis: proptérea benedíxit te Deus in ætérnum, et in sǽculum sǽculi."}],"Secreta":[{"k":"text","la":"Exáudi, Dómine, preces nostras: et, ut digna sint múnera, quæ óculis tuæ majestátis offérimus, subsídium nobis tuæ pietátis impénde."},{"k":"macro","name":"Per Dominum"}],"Communio":[{"k":"ref","la":"Luc 2:26"},{"k":"text","la":"Respónsum accépit Símeon a Spíritu Sancto, non visúrum se mortem, nisi vidéret Christum Dómini."}],"Postcommunio":[{"k":"text","la":"Quǽsumus, Dómine, Deus noster: ut sacrosáncta mystéria, quæ pro reparatiónis nostræ munímine contulísti, intercedénte beáta María semper Vírgine, et præsens nobis remédium esse fácias et futúrum."},{"k":"macro","name":"Per Dominum"}],"Prelude":[{"k":"head","la":"De Benedictione Candelarum"},{"k":"rubric","la":"Si candelarum benedictio et processio, ob defectum ministrorum sacrorum, forma solemni fieri nequeat, licet formam simplicem adhibere, etiam absque cantu, dummodo tres saltem ministrantes celebranti inserviant."},{"k":"rubric","la":"Celebrans indutus pluviali albo, vel sine Casula, cum ministris similiter indutis, procedit ad benedicendum Candelas, in medio ante Altare vel ad latus Epistolæ positas, et ipse ibidem stans versus ad Altare, dicit manibus junctis in tono feriali:"},{"k":"sep"},{"k":"text","la":"Dóminus vobíscum.","mark":"V"},{"k":"text","la":"Et cum spíritu tuo.","mark":"R"},{"k":"text","la":"Orémus. Domine sancte, Pater omnípotens, ætérne Deus, qui ómnia ex níhilo creásti, et jussu tuo per ópera apum hunc liquorem ad perfectionem cérei veníre fecísti: et qui hodiérna die petitiónem justi Simeónis implésti: te humíliter deprecámur; ut has candélas ad usus hóminum et sanitátem córporum et animárum, sive in terra sive in aquis, per invocatiónem tui sanctíssimi nóminis et per intercessiónem beátæ Maríæ semper Vírginis, cujus hódie festa devóte celebrántur, et per preces ómnium Sanctórum tuórum, bene + dícere et sancti + ficáre dignéris: et hujus plebis tuæ, quæ illas honorífice in mánibus desíderat portare teque cantando laudare, exáudias voces de cœlo sancto tuo et de sede majestátis tuæ: et propítius sis ómnibus clamántibus ad te, quos redemísti pretióso Sánguine Fílii tui: Qui tecum vivit et regnat in sǽcula sæculórum."},{"k":"text","la":"Amen.","mark":"R"},{"k":"sep"},{"k":"text","la":"Orémus. Omnípotens sempitérne Deus, qui hodiérna die Unigénitum tuum ulnis sancti Simeónis in templo sancto tuo suscipiéndum præsentásti: tuam súpplices deprecámur cleméntiam; ut has candélas, quas nos fámuli tui, in tui nóminis magnificéntiam suscipiéntes, gestáre cúpimus luce accénsas, bene + dícere et sancti + ficáre atque lúmine supérnæ benedictiónis accéndere dignéris: quaténus eas tibi Dómino, Deo nostro, offeréndo digni, et sancto igne dulcíssimæ caritátis tuæ succénsi, in templo sancto glóriæ tuæ repræsentári mereámur. Per eundem Christum Dominum nostrum."},{"k":"text","la":"Amen.","mark":"R"},{"k":"sep"},{"k":"text","la":"Orémus. Dómine Jesu Christe, lux vera, quæ illúminas omnem hóminem veniéntem in hunc mundum: effúnde bene + dictiónem tuam super hos céreos, et sancti + fica eos lúmine grátiæ tuæ, et concéde propítius; ut, sicut hæc luminária igne visíbili accénsa noctúrnas depéllunt ténebras; ita corda nostra invisíbili igne, id est, Sancti Spíritus splendóre illustráta, ómnium vitiórum cæcitáte cáreant: ut, purgáto mentis óculo, ea cérnere possímus, quæ tibi sunt plácita et nostræ salúti utília; quaténus post hujus sǽculi caliginósa discrímina ad lucem indeficiéntem perveníre mereámur. Per te, Christe Jesu, Salvátor mundi, qui in Trinitáte perfécta vivis et regnas Deus, in sǽcula sæculórum."},{"k":"text","la":"Amen.","mark":"R"},{"k":"sep"},{"k":"text","la":"Orémus. Omnípotens sempitérne Deus, qui per Móysen fámulum tuum puríssimum ólei liquórem ad luminária ante conspéctum tuum júgiter concinnánda præparári jussísti: bene + dictiónis tuæ grátiam super hos céreos benígnus infúnde; quaténus sic adminístrent lumen extérius, ut, te donánte, lumen Spíritus tui nostris non desit méntibus intérius. Per Christum Dominum nostrum."},{"k":"text","la":"Amen.","mark":"R"},{"k":"sep"},{"k":"text","la":"Orémus. Dómine Jesu Christe, qui hodiérna die, in nostræ carnis substántia inter hómines appárens, a paréntibus in templo es præsentátus: quem Símeon venerábilis senex, lúmine Spíritus tui irradiátus, agnóvit, suscépit et benedíxit: præsta propítius; ut, ejúsdem Spíritus Sancti grátia illumináti atque edócti, te veráciter agnoscámus et fidéliter diligámus: Qui cum Deo Patre in unitáte ejúsdem Spíritus Sancti vivis et regnas Deus in sǽcula sæculórum."},{"k":"text","la":"Amen.","mark":"R"},{"k":"rubric","la":"Finitis Orationibus, celebrans ponit incensum in thuríbulum: deinde ter aspergit candelas aqua benedícta, dicendo Antiphonam “Aspérges me”, sine cantu et sine Psalmo: et ter adolet incenso."},{"k":"sep"},{"k":"head","la":"De Distributione Candelarum"},{"k":"rubric","la":"Tum dignior ex Clero accedit ad Altare, et ab eo Celebrans accipit Candelam, non genuflectens nec osculans manum illius. Postea Celebrans stans in medio ante Altare versus ad populum, distríbuit Candelas, primum digniori, a quo ipse acceperat; deinde Diacono et Subdiacono paratis, et aliis Clericis singulatim per ordinem, ultimo laicis: omnibus genuflectentibus, Candelam et manum Celebrantis osculantibus, exceptis Prælatis, si adsint. Et cum inceperit distribuere Candelas, a Choro cantatur:"},{"k":"sep"},{"k":"ref","la":"Antiphona Luc 2:32"},{"k":"text","la":"Ant. Lumen ad revelatiónem géntium et glóriam plebis tuæ Israël."},{"k":"ref","la":"Luc 2:29-31"},{"k":"text","la":"Nunc dimíttis servum tuum, Dómine, secúndum verbum tuum in pace"},{"k":"rubric","la":"Deinde repetitur tota Antiphona “Lumen ad revelatiónem géntium” quæ similiter repetitur post quemlibet Versum."},{"k":"text","la":"Ant. Lumen ad revelatiónem géntium et glóriam plebis tuæ Israël."},{"k":"text","la":"Quia vidérunt óculi mei salutáre tuum."},{"k":"text","la":"Ant. Lumen ad revelatiónem géntium et glóriam plebis tuæ Israël."},{"k":"text","la":"Quod parásti ante fáciem ómnium populorum."},{"k":"text","la":"Ant. Lumen ad revelatiónem géntium et glóriam plebis tuæ Israël."},{"k":"text","la":"Glória Patri, et Fílio, et Spirítui Sancto."},{"k":"text","la":"Ant. Lumen ad revelatiónem géntium et glóriam plebis tuæ Israël."},{"k":"text","la":"Sicut erat in princípio, et nunc, et semper, et in sǽcula sæculórum. Amen."},{"k":"text","la":"Ant. Lumen ad revelatiónem géntium et glóriam plebis tuæ Israël."},{"k":"sep"},{"k":"rubric","la":"Deinde Sacerdos dicit:"},{"k":"text","la":"Orémus."},{"k":"text","la":"Exáudi, quǽsumus, Dómine, plebem tuam: et, quæ extrinsécus ánnua tríbuis devotióne venerári, intérius asséqui grátiæ tuæ luce concéde. Per Christum, Dóminum nostrum."},{"k":"text","la":"Amen.","mark":"R"},{"k":"sep"},{"k":"head","la":"De Processione"},{"k":"rubric","la":"Primo Celebrans ponit incensum in thuribulum: postea Diaconus vertens se ad populum, dicit:"},{"k":"text","la":"Procedámus in pace.","mark":"V"},{"k":"text","la":"In nómine Christi. Amen.","mark":"R"},{"k":"rubric","la":"Præcedit thuriferarius cum thuribulo fumiganti: deinde Subdiaconus paratus, deferens Crucem, medius inter duos Acolythos cum candelabris accensis: sequitur Clerus per ordinem, ultimo Celebrans cum Diacono a sinistris, omnes cum Candelis accensis in manibus: et cantantur Antiphonæ sequentes:"},{"k":"text","la":"Ant. Adórna thálamum tuum, Sion, et súscipe Regem Christum: ampléctere Maríam, quæ est cœléstis porta: ipsa enim portat Regem glóriæ novi lúminis: subsístit Virgo, addúcens mánibus Fílium ante lucíferum génitum: quem accípiens Símeon in ulnas suas, prædicávit pópulis, Dóminum eum esse vitæ et mortis et Salvatórem mundi."},{"k":"sep"},{"k":"ref","la":"Luc 2:26, 27 et 28-29"},{"k":"text","la":"Ant. Respónsum accépit Símeon a Spíritu Sancto, non visúrum se mortem, nisi vidéret Christum Dómini: et cum indúcerent Púerum in templum, accépit eum in ulnas suas, et benedíxit Deum, et dixit: Nunc dimíttis servum tuum, Dómine, in pace."},{"k":"text","la":"Cum indúcerent púerum Jesum parentes ejus, ut fácerent secúndum consuetúdinem legis pro eo, ipse accépit eum in ulnas suas.","mark":"V"},{"k":"sep"},{"k":"rubric","la":"Et ingrediendo Ecclesiam, cantatur:"},{"k":"text","la":"Obtulérunt pro eo Dómino par túrturum, aut duos pullos columbárum: * Sicut scriptum est in lege Dómini.","mark":"V"},{"k":"text","la":"Postquam impléti sunt dies purgatiónis Maríæ, secúndum legem Moysi, tulérunt Jesum in Jerúsalem, ut sísterent eum Sicut scriptum est in lege Dómini.","mark":"V"},{"k":"text","la":"Glória Patri, et Fílio, et Spirítui Sancto.","mark":"V"},{"k":"text","la":"Sicut scriptum est in lege Dómini.","mark":"R"},{"k":"rubric","la":"Finita Processione, celebrans et ministri accipiunt paramenta pro Missa. In Missa quæ benedictionem candelarum sequitur, omittuntur psalmus “Iudica me, Deus” cum sua antiphona, necnon confessio cum absolutione, versibus sequentibus atque orationibus “Aufer a nobis” et “Oramus te, Domine”. Sacerdos igitur cum ad altare accesserit, statim illud ascendit et osculatur in medio. Candelæ in manibus tenentur ad Evangelium et toto Canone."}]},"hr":{"7ff4bedd350271d3":{"t":"Ps 47, 10-11, Ps 47, 2\n(Ps 47, 10-11) Primili smo, Bože tvoju milost usred tvojeg hrama. Kao što je tvoje ime, Bože, tako neka bude i tvoja hvala do kraja zemlje. Pravde je puna tvoja desnica. (Ps 47, 2) Velik je Gospodin i veoma dostojan hvale u gradu Boga našega, na svetoj gori njegovoj.\n<i>Slava Ocu, i Sinu, i Duhu Svetomu. Kako bijaše na početku, tako i sada i vazda i u vijeke vjekova. Amen</i>.\n(Ps 47, 10-11) Primili smo, Bože tvoju milost usred tvojeg hrama. Kao što je tvoje ime, Bože, tako neka bude i tvoja hvala do kraja zemlje. Pravde je puna tvoja desnica.","kn":"(Ps. 47,\" 10). Primili smo, .Bože, milosrđe .Tvoje usred hrama\" Tvojega. Kao što. ime Tvoje, Bože, tako i hvala Tvoja dopire do krajeva zemaljskih; pravde je puna desnica Tvoja. (Ps. 47, 2),' Velik je Gospodin i slavan veoma u gradu Boga našega, na svetoj gori svojoj. Slava Ocu . . . Primili smo . . .","knRef":"Kniewald 1942, str. 384–385 (snimka 193) (OCR)"},"d5a5294ec3ba7cb4":{"t":"<i>Pomolimo se</i>.\nSvemogući vječni Bože, ponizno molimo tvoje veličanstvo, daj, kao što je tvoj jedinorođeni Sin u naravi ljudskog tijela na današnji dan bio prikazan u hramu, da tako i mi budemo očišćena srca prikazani tebi.\n<i>Po istom Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>.","kn":"Svemogući vječni Bože, veličanstvo Tvoje smjerno molimo, učini, kao što se Jedinorođeni Tvoj današnji dan sa biti našega tijela prikaza u hramu, tako da se i mi Tebi prikazujemo očišćenim dušama, po G. n.","knRef":"Kniewald 1942, str. 498–499 (snimka 250) (OCR)"},"f3f5db0a307e0c3c":{"t":"Mal 3, 1-4\nČitanje Malahije proroka. Ovo govori Gospodin Bog: »Evo, ja šaljem svoga glasnika koji će pripremiti put preda mnom. I Gospodin, kojega vi tražite, i anđeo zavjeta, kojega vi želite, doći će u svoj hram. Evo dolazi!« govori Gospodin nad vojskama. »A tko može misliti na dan njegova dolaska, i tko će se održati, kad se on javi? On će biti kao oganj koji rastapa i kao trava za bijeljenje. I sjedit će kao onaj koji tali i čisti srebro, i očistit će Levijeve sinove i pre–topit će ih kao zlato i srebro i oni će prinositi Gospodinu žrtve u pravednosti. A žrtva Jude i Jeruzalema bit će Bogu ugodna kao u prošle vjekove i u davne godine«, govori Gospodin svemogući.","kn":"Čitanje proroka Malahije (3, 1-4). Ovo govori Gospodin Bog; Evo, ja šaljem svoga glasnika, koji će pripraviti put preda mnom. I Gospodin, kojega vi tražite, i Anđeo zavjeta, kojega vi želite, doći će Svijećnica 2. II. odmah u svoj hram. Evo dolazi, govori Gospodin vojska, A tko može pomišljati na dan njegova dolaska, i tko će moći podnijeti njegov pogled? Jer on će biti kao oganj, koji topi. i kao trava za pranje, ^ i sjedit će kao onaj, koji tali i čisti srebro, 1 očisHt će Levijeve sinove i pretopit će ih kao zlaito i srebroj^ a oni će prinositi žrtve Gospodinu u pravdi. A žrtva Judina i Jeruzalemska bit će ugodna kao i prošlih vjekova i davnine, govori svemogući Gospodin.","knRef":"Kniewald 1942, str. 498–499 (snimka 250) (OCR)"},"4bc0fd140dec4647":{"t":"Ps 47, 10-11, Ps 47, 9\nPrimili smo, Bože, tvoje milosrđe usred tvoga hrama. Kao što tvoje ime, Bože, tako i tvoja slava dopire do krajeva zemlje. Sto smo čuli, to i vidimo u građu Boga našega, na njegovoj svetoj gori.\n\nLk 2, 29-32\nSad otpusti slugu svoga, Gospodine, po riječi svojoj u miru. Jer vidješe oči moje spasenje tvoje, koje si pripravio pred licem sviju naroda. Svjetlo na prosvijetljen je naroda i na slavu puka tvoga izraelskoga.","v":"∅ → v; ∅ → v","kn":"(Ps. 47, 10, 11). Primili smo, Bože, milosrđe Tvoje usred hrama Tvojega; kao što ime Tvoje Brae, tako i hvala Tvoja dopire do krajeva zemaljskih. Sto smo čuli, to vidimo u gradu Boga našega., na gori svetoj Tvojoj.\n\n(Luka 2, 29-32). Sad otpuštaš s mirom slu'gu svoga, Gospodine, po riječi svojoj, jer vidješe oči moje spasenje Tvoje, koji si pripravio pred licem svih naroda; svijetlo da rasvijetli neznabošce i slavu naroda Tvoga Izraelskoga.","knRef":"Kniewald 1942, str. 500–501 (snimka 251) (OCR)"},"b939d9393ccdf639":{"t":"Lk 2, 22-32\nSlijedi sveto Evanđelje po Luki. U ono vrijeme: Kad su se navršili dani Marijina očišćenja prema Mojsijevu zakonu, donesu Isusa u Jeruzalem da ga prikažu Gospodinu kako je pisano u Gospodnjem zakonu; Svaki muški prvorođenac neka bude posvećen Gospodinu, te da prinesu žrtvu kako je rečeno u Gospodnjem zakonu: Par grlica ili dva golubića. – A u Jeruzalemu je živio pravedan i bogobojazan čovjek po imenu Simun. On je čekao Izraelovu utjehu, i Duh je Sveti bio u njemu. I Duh mu Sveti objavi da neće umrijeti dok ne vidi Krista Gospodnjega. I po nadahnuću dođe u hram. A kad su roditelji donijeli dijete Isusa da za njega izvrše po propisu zakona, on ga uze u naručje, zahvali Bogu i reče: Sad otpusti, Gospodine, svoga slugu da prema tvojoj riječi ide u miru, jer su moje oči vidjele tvoje spasenje sto si ga pripravio svim narodima: Svjetlo da rasvijetli pogane i na slavu svojem narodu Izraelskom.","kn":"t Slijedi sveto evanđelje po Luki (2, 22-32). U ono vrijeme, kad su se navršfli dani Marijina očišćenja po Mojsijevu zakonu, donesu Isusa u Jeruzalem, da ga prikazu Gospodinu, kako je projpisano u Gospodnjem zakonu; Svaki muški prvorođenac bit će posvećen Gospodinu, i da prinesu žrtvu, kako je rečeno u Gospodnjem zakonu: par grlica ili dva golubića. A bio je u Jeruzalemu čovjek, koji se ^^ao^ Simun. I taj pravedni i bogobojazni čovjek iščekivao je Izraelovu utjehu i Duh Sveti bio je u njemu. I objavi mu Duh Sveti, da ne će umrijeti prije nego vidi Krista Gospodnjega. I dođe po nadahnuću u hram, I kad su donijeli dijete Isusa njegovi roditelji, da za njega učine prema propisu zakona, uze ga on u naručaj, zahvali Bogu i reče: Gospodine, sada u miru otpuštaš svoga slugu po svojoj riječi, jer su vidjele moje oči tvoj spas, koji si pripravio svim narodima: Svijetlo, da rasvijetli neznabošce i slavu tvojemu narodu Izraelu. ,","knRef":"Kniewald 1942, str. 500–501 (snimka 251) (OCR)"},"f13ce0f2fb02da20":{"t":"Ps 44, 3\nRazlita je milina na tvojim usnama, zbog toga te Bog blagoslovi u vijeke, i u vijeke vjekova.","kn":"(Ps. 44, 3). Razlita je milost na usnama tvojim, toga radi blagoslovi te Bog u vijeke, i u vijeke vijeka.","knRef":"Kniewald 1942, str. 500–501 (snimka 251) (OCR)"},"3efe908bd3c83a3f":{"t":"Usliši, Gospodine, naše molitve, i udijeli nam pomoć svoje dobrote da darovi, koje prinosimo očima tvoga veličanstva, budu dostojni.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>.","kn":"Usliši, Goispodine, molitve naše, i daj nam pomoć Tvoje blagosti, da darovi, što ih prinosimo, budu dostojni očima veličanstva Tvojega, po G. n.","knRef":"Kniewald 1942, str. 500–501 (snimka 251) (OCR)"},"46276ff06c5f858a":{"t":"Uistinu je dostojno i pravedno, pravo i spasonosno, da vazda i svagdje zahvaljujemo tebi, Gospodine sveti Oče, svemogući i vječni Bože: jer je po tajni utjelovljene Riječi očima naše duše sinula nova svjetlost tvoga sjaja. Te dok tjelesnim očima spoznajemo Boga, on nas zanosi ljubavlju prema nevidljivim dobrima. I stoga s anđelima i arkanđelima, s prijestoljima i gospodstvima i sa svom nebeskom vojskom pjesmu tvoje slave pjevamo bez prestanka:","kn":"Uistinu je dostojno i pravedno, pravo i spasonosno, da vazda i svagdje zahvaljujemo Tebi, Gospodine sveti, Oče svemogući, vječni Bože, jer je otajstvom utjelovljene Riječi očima naše duše zasjalo novo svijetlo Tvoje sjajnosti, te nas Bog, dok ga spoznajemo u vidljivom obličju, privlači da ljubimo i nevidljive stvari. I zato pjevamo pjesmu slave Tvoje s anđelima i arkanđelima, s prijestolima 1 s gospodstvima, sa svom silom nebeske vojske govoreći bez prestanka:","knRef":"Kniewald 1942, str. 20–21 (snimka 11) (OCR)"},"224203c063ede4f1":{"t":"Lk 2, 26\nOdgovor primi Šimun od Duha Svetoga da neće umrijeti, dok ne vidi Krista Gospodnjega.","kn":"(Luka 2, 26). Odgovor primi Simeon od Duha Svetoga, da ne će ugledati smrti, dok ne vidi Krista Gospodnjega.","knRef":"Kniewald 1942, str. 500–501 (snimka 251) (OCR)"},"60bea15f8b25535c":{"t":"<i>Pomolimo se</i>.\nMolimo, Gospodine Bože naš, daj da nam sveta otajstva, koja si ustanovio za naše spasenje, budu po zagovoru blažene Marije vazda Djevice lijek i sada i ubuduće.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>.","kn":"Molimo, Gospodine, Bože naš, da ove presvete tajne, što si ih udijelio za utvrđenje ^našega obnovljenja, budu nama PQ zagovoru blažene Marije, vazda Djevice, 1 sadašnji i budući lijek, po G. n.","knRef":"Kniewald 1942, str. 500–501 (snimka 251) (OCR)"},"0bcc53ff01328c06":{"t":"Ps 47, 10-11, Ps 47, 9\nPrimili smo, Bože, tvoje milosrđe usred tvoga hrama. Kao što tvoje ime, Bože, tako i tvoja slava dopire do krajeva zemlje. Sto smo čuli, to i vidimo u građu Boga našega, na njegovoj svetoj gori.\n\n<i>Aleluja</i>, <i>aleluja</i>.\nStarac je nosio Dijete, a Dijete je upravljalo starcem. <i>Aleluja</i>.","kn":"(Ps. 47, 10, 11). Primili smo, Bože, milosrđe Tvoje usred hrama Tvojega; kao što ime Tvoje Brae, tako i hvala Tvoja dopire do krajeva zemaljskih. Sto smo čuli, to vidimo u gradu Boga našega., na gori svetoj Tvojoj.\n\nAleluja, aleluja. Starac je dijete nosio, a dijete je starcem upravljalo Aleluja.","knRef":"Kniewald 1942, str. 500–501 (snimka 251) (OCR)"}},"variants":{"paschal":{"GradualeP":[{"k":"text","la":"Allelúja, allelúja."},{"k":"ref","la":"Num 17:8"},{"k":"text","la":"Virga Jesse flóruit: Virgo Deum et hóminem génuit: pacem Deus réddidit, in se reconcílians ima summis."},{"k":"ref","la":"Luc 1:28"},{"k":"text","la":"Ave, María, grátia plena; Dóminus tecum: benedícta tu in muliéribus. Allelúja."}]}}});
